package com.wildernessagility;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import javax.inject.Inject;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.components.TitleComponent;

public class WildernessAgilityOverlay extends OverlayPanel
{
	private static final Color STREAK_COLOR_LOW = Color.RED;
	private static final Color STREAK_COLOR_MEDIUM = Color.YELLOW;
	private static final Color STREAK_COLOR_HIGH = Color.GREEN;
	private static final Color STREAK_COLOR_MAX = new Color(170, 0, 255);

	private final WildernessAgilityPlugin plugin;

	@Inject
	private WildernessAgilityOverlay(WildernessAgilityPlugin plugin, WildernessAgilityConfig config)
	{
		this.plugin = plugin;
		setPosition(config.overlayPosition().getPosition());
		setLayer(OverlayLayer.ABOVE_WIDGETS);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!plugin.isInTargetArea())
		{
			return null;
		}

		panelComponent.getChildren().clear();

		panelComponent.getChildren().add(TitleComponent.builder()
			.text("Wilderness Agility")
			.color(Color.ORANGE)
			.build());

		if (plugin.isStreakConfirmed())
		{
			int streak = plugin.getStreak();
			panelComponent.getChildren().add(LineComponent.builder()
				.left("Streak:")
				.right(String.valueOf(streak))
				.rightColor(streakColor(streak))
				.build());
		}
		else
		{
			// The only value available is a persisted guess (e.g. right after startUp()) that hasn't
			// been confirmed yet this session - shown as unknown rather than potentially stale.
			panelComponent.getChildren().add(LineComponent.builder()
				.left("Streak:")
				.right("???")
				.rightColor(Color.GRAY)
				.build());
		}

		long profit = plugin.getTotalProfit();
		panelComponent.getChildren().add(LineComponent.builder()
			.left("GP:")
			.right(formatProfit(profit))
			.rightColor(profit >= 0 ? Color.GREEN : Color.RED)
			.build());

		if (plugin.isAlchemyMode())
		{
			panelComponent.getChildren().add(LineComponent.builder()
				.left("Blighted food:")
				.right(String.valueOf(plugin.getBlightedFoodCount()))
				.build());

			panelComponent.getChildren().add(LineComponent.builder()
				.left("Blighted pots:")
				.right(String.valueOf(plugin.getBlightedPotionCount()))
				.build());
		}

		panelComponent.getChildren().add(LineComponent.builder()
			.left("XP/hr:")
			.right(String.valueOf(plugin.getXpPerHour()))
			.build());

		return super.render(graphics);
	}

	private static Color streakColor(int streak)
	{
		if (streak <= 15)
		{
			return STREAK_COLOR_LOW;
		}
		if (streak <= 30)
		{
			return STREAK_COLOR_MEDIUM;
		}
		if (streak <= 60)
		{
			return STREAK_COLOR_HIGH;
		}
		return STREAK_COLOR_MAX;
	}

	private static String formatProfit(long profit)
	{
		long abs = Math.abs(profit);
		if (abs >= 1_000_000)
		{
			return String.format("%.2fM", abs / 1_000_000.0);
		}
		if (abs >= 100_000)
		{
			return (abs / 1000) + "k";
		}
		return abs + " gp";
	}
}

package com.wildernessagility;

import lombok.AllArgsConstructor;
