package com.wildernessagility;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Shape;
import java.util.ArrayList;
import java.util.List;
import javax.inject.Inject;
import net.runelite.api.DecorativeObject;
import net.runelite.api.GameObject;
import net.runelite.api.GroundObject;
import net.runelite.api.TileObject;
import net.runelite.api.WallObject;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.outline.ModelOutlineRenderer;

public class ObstacleGuideOverlay extends Overlay
{
	private static final Color HIGHLIGHT_COLOR = Color.GREEN;
	private static final int OUTLINE_WIDTH = 3;
	private static final int OUTLINE_FEATHER = 2;
	private static final long FLASH_PERIOD_MILLIS = 800;
	private static final int FILL_ALPHA = 60;

	private final WildernessAgilityPlugin plugin;
	private final WildernessAgilityConfig config;
	private final ModelOutlineRenderer modelOutlineRenderer;

	@Inject
	private ObstacleGuideOverlay(WildernessAgilityPlugin plugin, WildernessAgilityConfig config,
		ModelOutlineRenderer modelOutlineRenderer)
	{
		this.plugin = plugin;
		this.config = config;
		this.modelOutlineRenderer = modelOutlineRenderer;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_SCENE);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!config.showObstacleGuide() || !plugin.isInTargetArea())
		{
			return null;
		}

		List<TileObject> targets = plugin.getCurrentObstacleObjects();
		if (targets.isEmpty())
		{
			return null;
		}

		// ModelOutlineRenderer dispatches correctly across every TileObject subtype (GameObject,
		// GroundObject, WallObject, DecorativeObject) - unlike TileObject.getClickbox(), which was
		// tried first but only rendered reliably for plain GameObjects (the pipe), never for the
		// other obstacles (Ground/Wall/DecorativeObject instances).
		Color outlineColor = flash(HIGHLIGHT_COLOR);
		Color fillColor = new Color(HIGHLIGHT_COLOR.getRed(), HIGHLIGHT_COLOR.getGreen(), HIGHLIGHT_COLOR.getBlue(), FILL_ALPHA);
		for (TileObject target : targets)
		{
			modelOutlineRenderer.drawOutline(target, OUTLINE_WIDTH, outlineColor, OUTLINE_FEATHER);

			// The object's actual convex hull (its real rendered silhouette), not a ground tile poly -
			// a plain tile-ground fill was tried first and only ever shaded the single base tile under
			// the object's anchor point, which for anything taller/wider than one tile (the ropeswing
			// pole, the log balance beam) read as shading the tile nearest the obstacle rather than the
			// obstacle itself. getConvexHull() is a different API from getClickbox() (which wasn't
			// reliable here) - this is the same one RuneLite's own Object Indicators plugin uses for its
			// fill/area highlight mode, and it's defined per concrete subtype rather than on TileObject.
			for (Shape hull : convexHulls(target))
			{
				graphics.setColor(fillColor);
				graphics.fill(hull);
			}
		}

		return null;
	}

	private static List<Shape> convexHulls(TileObject object)
	{
		if (object instanceof GameObject)
		{
			return nonNull(((GameObject) object).getConvexHull());
		}
		if (object instanceof WallObject)
		{
			WallObject wallObject = (WallObject) object;
			return nonNull(wallObject.getConvexHull(), wallObject.getConvexHull2());
		}
		if (object instanceof DecorativeObject)
		{
			DecorativeObject decorativeObject = (DecorativeObject) object;
			return nonNull(decorativeObject.getConvexHull(), decorativeObject.getConvexHull2());
		}
		if (object instanceof GroundObject)
		{
			return nonNull(((GroundObject) object).getConvexHull());
		}
		return nonNull(object.getCanvasTilePoly());
	}

	private static List<Shape> nonNull(Shape... shapes)
	{
		List<Shape> result = new ArrayList<>(shapes.length);
		for (Shape shape : shapes)
		{
			if (shape != null)
			{
				result.add(shape);
			}
		}
		return result;
	}

	private static Color flash(Color base)
	{
		double phase = (System.currentTimeMillis() % FLASH_PERIOD_MILLIS) / (double) FLASH_PERIOD_MILLIS;
		double alpha = 0.35 + 0.65 * Math.abs(Math.sin(phase * Math.PI));
		return new Color(base.getRed(), base.getGreen(), base.getBlue(), (int) Math.round(alpha * 255));
	}
}

