@Slf4j
@PluginDescriptor(
	name = "Wilderness Agility Course Tracker",
	description = "Streak tracking, loot/GP value, and XP per hour for the Wilderness Agility Course, plus a next-obstacle guide",
	tags = {"wilderness", "agility", "dispenser", "streak", "loot", "blighted"}
)
public class WildernessAgilityPlugin extends Plugin
{
	// Confirmed via RuneLite's built-in Agility plugin (Courses.WILDERNESS).
	static final int COURSE_REGION = 11837;

	// No RuneLite gameval constant exists for this object yet - confirmed against the OSRS Wiki's
	// own object infobox (id=53224); the same numbering scheme matched all four Wilderness
	// obstacle objects above exactly, so this is trusted but should be double-checked live.
	private static final int AGILITY_DISPENSER_OBJECT_ID = 53224;

	// RuneLite's built-in Agility plugin's own clickbox-outline toggle (confirmed against its
	// AgilityConfig source: @ConfigGroup("agility"), showClickboxes()) - ConfigManager isn't
	// namespace-isolated between plugins, so this is suppressed while in the course to avoid
	// clashing with the obstacle guide, and restored to whatever it was on leaving.
	private static final String AGILITY_PLUGIN_CONFIG_GROUP = "agility";
	private static final String AGILITY_SHOW_CLICKBOXES_KEY = "showClickboxes";

	// The lap's obstacle order, per the user's own confirmed course knowledge - cycles back to
	// DISPENSER after ROCKS. ObstacleStage.next() walks this order.
	private enum ObstacleStage
	{
		DISPENSER, OBSTACLE_PIPE, ROPESWING, STEPPING_STONE, LOG_BALANCE, ROCKS;

		ObstacleStage next()
		{
			ObstacleStage[] values = values();
			return values[(ordinal() + 1) % values.length];
		}
	}

	// Object ids for each obstacle, confirmed against RuneLite's own built-in Agility plugin source
	// (Obstacles.java's "// Wilderness" block lists exactly these five ids for this course).
	private static final Map<Integer, ObstacleStage> OBSTACLE_ID_TO_STAGE = Map.of(
		AGILITY_DISPENSER_OBJECT_ID, ObstacleStage.DISPENSER,
		ObjectID.OBSTICAL_PIPE2, ObstacleStage.OBSTACLE_PIPE,
		ObjectID.OBSTICAL_ROPESWING2, ObstacleStage.ROPESWING,
		ObjectID.STEPPINGSTONE1, ObstacleStage.STEPPING_STONE,
		ObjectID.WILDERNESS_LOG_BALANCE1, ObstacleStage.LOG_BALANCE,
		ObjectID.WILDCLIMBINGROCK, ObstacleStage.ROCKS);

	// ROCKS is made of three separate rock objects sharing the same id, any one of which completes
	// the obstacle - confirmed by the user - so all three are tracked and highlighted at once.
	// Every other obstacle has exactly one genuine target (e.g. the pipe has two physical ends but
	// only one is the real interactive one), so only the first instance seen is kept for those.
	private static final Set<ObstacleStage> MULTI_TARGET_STAGES = Set.of(ObstacleStage.ROCKS);

	// How long to wait, after the obstacle guide starts expecting a given obstacle, for success to be
	// confirmed (an Agility XP gain for most obstacles, or the lap-completion chat message
	// specifically for Climb Rocks) before assuming the attempt failed. Generous, since it only needs
	// to rule out a genuine failure, not react instantly - too short a window risks a late-arriving
	// confirmation being missed entirely.
	private static final int PENDING_CONFIRMATION_TIMEOUT_TICKS = 30;

	// A sanity cap on the XP-gain confirmation below: real per-obstacle XP for the four gated stages
	// tops out around 20, but other Agility XP sources exist while standing in the course area (e.g.
	// redeeming Wilderness agility tickets for a lump sum, confirmed live at 34,500 XP in one event) -
	// this stops a gain that large from being mistaken for confirming a tiny obstacle.
	private static final int MAX_PLAUSIBLE_OBSTACLE_XP = 100;

	// How recent a click on a given obstacle has to be for an XP gain to trust it as that obstacle's
	// own confirmation (see onStatChanged). Confirmed live (client log) that a normal Log Balance
	// walk-across alone can take 14+ seconds (~23 ticks) between the click and the XP landing, and a
	// fail-and-recover (falling into the pit, climbing out, walking back to retry) takes considerably
	// longer than that - a short window was silently rejecting real completions every time. currentStage
	// matching is the real safeguard against confirming the wrong obstacle, so this just needs to rule
	// out a stale click from a completely different, much-earlier attempt - generous is fine.
	private static final int CLICK_CONFIRMATION_WINDOW_TICKS = 100;

	// Restricts "does this message mention agility/dispenser" matching to actual game-generated text
	// (confirmed live: the dispenser's own responses are GAMEMESSAGE or SPAM) - without this, an
	// unrelated player chat message that happens to contain the word "agility" (confirmed live: a
	// FRIENDSCHAT message, "Wildy course makes training agility fun") could falsely be read as the
	// dispenser responding.
	private static final Set<ChatMessageType> GAME_MESSAGE_TYPES = Set.of(ChatMessageType.GAMEMESSAGE, ChatMessageType.SPAM);

	private static final Set<Integer> SKELETON_NPC_IDS = Set.of(
		NpcID.WILDY_AGILITY_SKELETON_1, NpcID.WILDY_AGILITY_SKELETON_2, NpcID.WILDY_AGILITY_SKELETON_3,
		NpcID.WILDY_AGILITY_SKELETON_4, NpcID.WILDY_AGILITY_SKELETON_5,
		NpcID.WILDY_AGILITY_SKELETON_1_LONGHUNT, NpcID.WILDY_AGILITY_SKELETON_2_LONGHUNT);

	private static final List<MenuAction> NPC_MENU_TYPES = List.of(
		MenuAction.NPC_FIRST_OPTION, MenuAction.NPC_SECOND_OPTION, MenuAction.NPC_THIRD_OPTION,
		MenuAction.NPC_FOURTH_OPTION, MenuAction.NPC_FIFTH_OPTION);

	// Dispenser drops are noted, so both the unnoted and certificate (noted) ids are tracked.
	private static final Set<Integer> BLIGHTED_FOOD_IDS = Set.of(
		ItemID.BLIGHTED_MANTARAY, ItemID.BLIGHTED_ANGLERFISH, ItemID.BLIGHTED_KARAMBWAN,
		ItemID.Cert.BLIGHTED_MANTARAY, ItemID.Cert.BLIGHTED_ANGLERFISH, ItemID.Cert.BLIGHTED_KARAMBWAN);

	private static final Set<Integer> BLIGHTED_POTION_IDS = Set.of(
		ItemID.BLIGHTED_4DOSE2RESTORE, ItemID.BLIGHTED_3DOSE2RESTORE, ItemID.BLIGHTED_2DOSE2RESTORE, ItemID.BLIGHTED_1DOSE2RESTORE,
		ItemID.Cert.BLIGHTED_4DOSE2RESTORE, ItemID.Cert.BLIGHTED_3DOSE2RESTORE, ItemID.Cert.BLIGHTED_2DOSE2RESTORE, ItemID.Cert.BLIGHTED_1DOSE2RESTORE);

	// The noted "junk armor" tier of dispenser rewards, confirmed against the OSRS Wiki's Agility
	// dispenser page. Small, fixed pool, so it's a hardcoded lookup rather than a fuzzy name search.
	private static final Set<Integer> ARMOR_REWARD_IDS = Set.of(
		ItemID.ADAMANT_FULL_HELM, ItemID.ADAMANT_PLATEBODY, ItemID.ADAMANT_PLATELEGS,
		ItemID.MITHRIL_CHAINBODY, ItemID.MITHRIL_PLATELEGS, ItemID.MITHRIL_PLATESKIRT,
		ItemID.RUNE_MED_HELM, ItemID.RUNE_CHAINBODY, ItemID.RUNE_KITESHIELD, ItemID.STEEL_PLATEBODY);

	// Names as they appear verbatim in the dispenser's reward chat message, mapped to item id for
	// price/alch-value lookup. Wilderness agility tickets and clue scrolls are deliberately excluded
	// - not GP-valued.
	private static final Map<String, Integer> DISPENSER_REWARD_ITEM_IDS = Map.ofEntries(
		Map.entry("Blighted manta ray", ItemID.BLIGHTED_MANTARAY),
		Map.entry("Blighted anglerfish", ItemID.BLIGHTED_ANGLERFISH),
		Map.entry("Blighted karambwan", ItemID.BLIGHTED_KARAMBWAN),
		Map.entry("Blighted super restore(4)", ItemID.BLIGHTED_4DOSE2RESTORE),
		Map.entry("Blighted super restore(3)", ItemID.BLIGHTED_3DOSE2RESTORE),
		Map.entry("Blighted super restore(2)", ItemID.BLIGHTED_2DOSE2RESTORE),
		Map.entry("Blighted super restore(1)", ItemID.BLIGHTED_1DOSE2RESTORE),
		Map.entry("Adamant full helm", ItemID.ADAMANT_FULL_HELM),
		Map.entry("Adamant platebody", ItemID.ADAMANT_PLATEBODY),
		Map.entry("Adamant platelegs", ItemID.ADAMANT_PLATELEGS),
		Map.entry("Mithril chainbody", ItemID.MITHRIL_CHAINBODY),
		Map.entry("Mithril platelegs", ItemID.MITHRIL_PLATELEGS),
		Map.entry("Mithril plateskirt", ItemID.MITHRIL_PLATESKIRT),
		Map.entry("Rune med helm", ItemID.RUNE_MED_HELM),
		Map.entry("Rune chainbody", ItemID.RUNE_CHAINBODY),
		Map.entry("Rune kiteshield", ItemID.RUNE_KITESHIELD),
		Map.entry("Steel platebody", ItemID.STEEL_PLATEBODY));

	// Matches "<col=ef1020>N x Item name</col>" segments in the dispenser's reward chat message.
	private static final Pattern DISPENSER_REWARD_ITEM_PATTERN = Pattern.compile("<col=ef1020>(\\d+) x ([^<]+)</col>");

	// The game itself reports the authoritative post-lap streak value via this chat message
	// (confirmed live: "Your Wilderness Agility reward streak is: <col=ff0000>3</col>") - used as a
	// resync point on every completed lap, correcting for anything the local reset/penalty tracking
	// below got wrong. Relying on it alone isn't enough though: it only arrives on a completed lap,
	// so between laps the displayed number needs its own reset/penalty handling to avoid going stale
	// the moment the player leaves, dies, or logs out.
	// This message also fires right when Climb Rocks (the final obstacle) is completed - before the
	// player physically reaches the dispenser - so its arrival also confirms the climb counted and
	// advances the obstacle guide to DISPENSER (see ObstacleStage above).
	private static final Pattern STREAK_PATTERN =
		Pattern.compile("Your Wilderness Agility reward streak is: <col=ff0000>(\\d+)</col>");

	private static final int STREAK_LOGOUT_HOP_PENALTY = 10;

	// Reminds the player to open their looting bag once so the ground-truth resync in
	// onItemContainerChanged() fires - the chat-message parsing alone can miss a reward if the wording
	// ever falls outside the known item table.
	private static final String LOOTING_BAG_REMINDER_MESSAGE =
		"Wilderness Agility: open your looting bag once this session for accurate loot tracking.";

	// If a persisted session hasn't been touched in this long, a fresh login treats it as over
	// rather than reviving old totals against a new, much shorter elapsed time.
	private static final Duration STALE_SESSION_THRESHOLD = Duration.ofMinutes(10);

	private static final String CONFIG_GROUP = "wildernessagility";
	private static final String KEY_STREAK = "streak";
	private static final String KEY_WAS_IN_COURSE = "wasInCourse";
	private static final String KEY_TOTAL_PROFIT = "sessionTotalProfit";
	private static final String KEY_TOTAL_XP = "sessionTotalXp";
	private static final String KEY_BLIGHTED_FOOD = "sessionBlightedFood";
	private static final String KEY_BLIGHTED_POTION = "sessionBlightedPotion";
	private static final String KEY_SESSION_START = "sessionStart";
	private static final String KEY_LAST_UPDATE = "lastUpdate";

	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private ItemManager itemManager;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private ConfigManager configManager;

	@Inject
	private WildernessAgilityConfig config;

	@Inject
	private WildernessAgilityOverlay overlay;

	@Inject
	private ObstacleGuideOverlay obstacleGuideOverlay;

	@Getter
	private int streak;

	// False whenever the displayed streak isn't actually known to be correct yet - e.g. right after
	// startUp(), the only value available is whatever was last persisted, which could be stale (a
	// force-closed session, or simply time having passed). Confirmed either by entering the course
	// fresh (streak is unambiguously 0 at that point) or by the lap-completion chat message (the
	// authoritative value). The overlay shows "???" instead of a number until this is true.
	@Getter
	private boolean streakConfirmed;

	@Getter
	private long totalProfit;

	@Getter
	private int totalXpGained;

	@Getter
	private int blightedFoodCount;

	@Getter
	private int blightedPotionCount;

	@Getter
	private Instant sessionStart;

	@Getter
	private int xpPerHour;

	// Resolved mode actually in effect (config.valuationMode() may just say Auto).
	@Getter
	private boolean alchemyMode;

	// Tracked by world position (not just stage), matching RuneLite's own built-in Agility plugin's
	// approach (event-driven, always replacing the cached reference on each spawn - no "sticky" logic
	// that could hold on to a stale one). Keying by position, rather than a single reference per
	// stage, is what lets a single-target obstacle with multiple physical objects sharing one id
	// (e.g. the pipe's two ends) be resolved deterministically in getCurrentObstacleObjects() without
	// ever blocking a legitimate respawn at either position from refreshing.
	private final Map<ObstacleStage, Map<WorldPoint, TileObject>> stageObjectsByPosition = new EnumMap<>(ObstacleStage.class);

	// The dispenser's own position, remembered independently of stageObjectsByPosition so it survives
	// even if the dispenser object itself briefly isn't tracked (e.g. right after a scene reload).
	private WorldPoint dispenserPosition;

	// For a single-target obstacle with more than one physical object sharing an id (e.g. the pipe has
	// two ends, only one of which is actually interactable - confirmed live: the farther one always
	// rejects the click), this remembers whichever position was ever seen closer to the dispenser, once
	// established. This is deliberately NOT recomputed from whatever's currently live in
	// stageObjectsByPosition on every call: the game spawns/despawns the two ends independently and
	// somewhat unpredictably, so there are frequent moments where only the farther (wrong) one is
	// present - recomputing from "currently live" alone would flicker the highlight onto it during those
	// windows. Once the closer position is identified, it's trusted permanently (until the cache is
	// cleared on a scene reload) rather than re-decided every frame.
	private final Map<ObstacleStage, WorldPoint> preferredPositionByStage = new EnumMap<>(ObstacleStage.class);

	private ObstacleStage currentStage;

	// The tick a given obstacle was last clicked, keyed by stage rather than a single "last click"
	// value - so an early click on the obstacle that's actually up next (a legitimate, fast player)
	// doesn't overwrite/lose the record of the current obstacle's own click while its XP confirmation is
	// still in flight. Used in onStatChanged to verify an XP gain actually came from the obstacle the
	// guide currently expects, not just any small Agility XP gain while in the area (e.g. repeatedly
	// re-doing the same obstacle without ever touching the one actually highlighted).
	private final Map<ObstacleStage, Integer> lastClickTickByStage = new EnumMap<>(ObstacleStage.class);

	// Set whenever currentStage changes, cleared once that obstacle's success is confirmed (an XP
	// gain, or a chat message for Rocks/Dispenser) or the confirmation window times out. Only used
	// for the timeout bookkeeping now - confirmation itself no longer requires a preceding click,
	// since a real click's own confirmation can otherwise arrive before the guide has caught up to
	// that stage (e.g. clicking Ropeswing while the guide is still confirming the pipe), silently
	// dropping the click and leaving the guide stuck.
	private Integer pendingSinceTick;

	// Whether we're currently overriding the built-in Agility plugin's clickbox setting, and what it
	// was before we touched it (null means it was unset/default, not literally false).
	private boolean clickboxesOverridden;
	private Boolean originalShowClickboxes;

	private Integer lastAgilityXp;
	private int lastLoggedRegion = -1;

	// Learned the first time the player falls from the course surface into whatever's below (pit,
	// dungeon, etc., depending on which obstacle was failed) - no RuneLite constant confirms this
	// id, so it's learned live from the region transition rather than hardcoded.
	private Integer pitRegionId;

	// Set in startUp() when resuming a session that ended mid-course - tells the first onGameTick
	// call to trust an immediately-observed non-course region as the pit, since the usual live
	// COURSE_REGION->elsewhere transition it learns from won't happen in that case.
	private boolean resumingMidCourse;

	// Set alongside resumingMidCourse in startUp(), but not cleared by onGameTick's own handling of
	// that flag - decoupled so the reminder isn't racing against exactly when the first game tick
	// happens to fire relative to the resolveMode() client-thread invoke below.
	private boolean pendingResumeLootingBagReminder;

	private boolean wasInCourseLastTick;

	@Override
	protected void startUp()
	{
		overlayManager.add(overlay);
		overlayManager.add(obstacleGuideOverlay);

		Long savedLastUpdate = configManager.getConfiguration(CONFIG_GROUP, KEY_LAST_UPDATE, Long.class);
		boolean stale = savedLastUpdate == null
			|| Duration.between(Instant.ofEpochMilli(savedLastUpdate), Instant.now()).compareTo(STALE_SESSION_THRESHOLD) > 0;

		if (stale)
		{
			totalProfit = 0;
			totalXpGained = 0;
			blightedFoodCount = 0;
			blightedPotionCount = 0;
			sessionStart = null;
			persistStats();
		}
		else
		{
			Long savedProfit = configManager.getConfiguration(CONFIG_GROUP, KEY_TOTAL_PROFIT, Long.class);
			Integer savedXp = configManager.getConfiguration(CONFIG_GROUP, KEY_TOTAL_XP, Integer.class);
			Integer savedFood = configManager.getConfiguration(CONFIG_GROUP, KEY_BLIGHTED_FOOD, Integer.class);
			Integer savedPotion = configManager.getConfiguration(CONFIG_GROUP, KEY_BLIGHTED_POTION, Integer.class);
			Long savedSessionStart = configManager.getConfiguration(CONFIG_GROUP, KEY_SESSION_START, Long.class);

			totalProfit = savedProfit == null ? 0 : savedProfit;
			totalXpGained = savedXp == null ? 0 : savedXp;
			blightedFoodCount = savedFood == null ? 0 : savedFood;
			blightedPotionCount = savedPotion == null ? 0 : savedPotion;
			sessionStart = (savedSessionStart == null || savedSessionStart < 0) ? null : Instant.ofEpochMilli(savedSessionStart);
		}

		// The streak is independent of the profit/XP session's own staleness timer above, so it's
		// always restored here regardless of `stale`.
		Integer savedStreak = configManager.getConfiguration(CONFIG_GROUP, KEY_STREAK, Integer.class);
		Boolean savedWasInCourse = configManager.getConfiguration(CONFIG_GROUP, KEY_WAS_IN_COURSE, Boolean.class);
		streak = savedStreak == null ? 0 : savedStreak;

		// Whatever streak we just restored is only a persisted guess until something this session
		// actually confirms it (entering the course fresh, or the lap-completion chat message) - the
		// overlay shows "???" instead of a number until then.
		streakConfirmed = false;

		if (savedWasInCourse != null && savedWasInCourse)
		{
			// The client wasn't shut down cleanly through a normal logout/hop transition while
			// mid-course last time (e.g. force-closed) - apply the same penalty a real logout would.
			log.info("Wilderness Agility: last session ended mid-course without a clean logout, applying logout penalty");
			streak = Math.max(0, streak - STREAK_LOGOUT_HOP_PENALTY);
			persistStreak();

			// Also: the plugin may be restarting while the player is already standing in the pit
			// (e.g. a dev-client relaunch mid-testing) rather than transitioning into it live - the
			// normal pit-region learning in onGameTick only fires on a live COURSE_REGION->elsewhere
			// transition, which won't happen if we start out already past it. This tells the first
			// onGameTick call to trust whatever non-course region it first observes as the pit.
			resumingMidCourse = true;
			pendingResumeLootingBagReminder = true;
		}

		log.info("Wilderness Agility: startUp complete - statsStale={}, restored streak={}", stale, streak);

		clientThread.invoke(this::resolveMode);
	}

	@Override
	protected void shutDown()
	{
		overlayManager.remove(overlay);
		overlayManager.remove(obstacleGuideOverlay);
		stageObjectsByPosition.clear();
		preferredPositionByStage.clear();
		dispenserPosition = null;
		lastClickTickByStage.clear();
		currentStage = null;
		pendingSinceTick = null;
		restoreAgilityClickboxes();
	}

	boolean isInTargetArea()
	{
		Player local = client.getLocalPlayer();
		if (local == null)
		{
			return false;
		}

		int region = local.getWorldLocation().getRegionID();
		return region == COURSE_REGION || (pitRegionId != null && region == pitRegionId);
	}

	List<TileObject> getCurrentObstacleObjects()
	{
		if (currentStage == null)
		{
			return List.of();
		}

		Map<WorldPoint, TileObject> byPosition = stageObjectsByPosition.get(currentStage);
		if (byPosition == null || byPosition.isEmpty())
		{
			return List.of();
		}

		if (MULTI_TARGET_STAGES.contains(currentStage))
		{
			return List.copyOf(byPosition.values());
		}

		// A single-target obstacle with more than one physical object sharing the same id (e.g. the
		// pipe's two ends) - the one ever seen closer to the dispenser is always the real, interactable
		// target (confirmed by the user: "it will never be the other one"). If that specific position
		// isn't currently spawned, show nothing rather than falling back to the farther one - it can't
		// be interacted with anyway.
		WorldPoint preferred = preferredPositionByStage.get(currentStage);
		if (preferred != null)
		{
			TileObject target = byPosition.get(preferred);
			return target == null ? List.of() : List.of(target);
		}

		// Only one position ever seen so far for this stage (or the dispenser's position isn't known
		// yet to compare against) - an arbitrary but stable pick beats showing nothing.
		return List.of(byPosition.values().iterator().next());
	}

	@Subscribe
	public void onGameTick(GameTick tick)
	{
		if (client.getGameState() != GameState.LOGGED_IN)
		{
			return;
		}

		boolean wasResumingMidCourse = resumingMidCourse;

		int region = currentRegion();
		if (region != lastLoggedRegion)
		{
			boolean firstObservation = lastLoggedRegion == -1;
			if (pitRegionId == null && region != COURSE_REGION
				&& (lastLoggedRegion == COURSE_REGION || (firstObservation && resumingMidCourse)))
			{
				pitRegionId = region;
				log.info("Wilderness Agility: learned pit/dungeon region {}", region);
			}
			resumingMidCourse = false;

			log.info("Wilderness Agility: region changed to {} (isInTargetArea={})", region, isInTargetArea());
			lastLoggedRegion = region;
		}

		boolean inCourseNow = isInTargetArea();
		if (wasInCourseLastTick && !inCourseNow)
		{
			// A genuine departure from the course while logged in, not a logout/hop - full reset.
			resetStreak();
			restoreAgilityClickboxes();
		}
		else if (!wasInCourseLastTick && inCourseNow)
		{
			// Freshly entered the course - the obstacle guide always starts at the dispenser.
			lastClickTickByStage.clear();
			advanceObstacleStage(ObstacleStage.DISPENSER, "entered course");
			suppressAgilityClickboxes();

			if (!wasResumingMidCourse)
			{
				// A genuine entry through the gate from outside (not resuming a session that was
				// already mid-course, e.g. a dev-client relaunch) - the streak is unambiguously 0 at
				// this point, so there's no need to wait for the chat message to know that for sure.
				streak = 0;
				persistStreak();
				streakConfirmed = true;
				log.info("Wilderness Agility: entered course fresh through the gate, streak confirmed at 0");
			}
		}

		if (inCourseNow != wasInCourseLastTick)
		{
			wasInCourseLastTick = inCourseNow;
			configManager.setConfiguration(CONFIG_GROUP, KEY_WAS_IN_COURSE, wasInCourseLastTick);
		}

		if (pendingSinceTick != null && client.getTickCount() - pendingSinceTick > PENDING_CONFIRMATION_TIMEOUT_TICKS)
		{
			if (currentStage == ObstacleStage.ROCKS)
			{
				// No lap-completion chat message arrived in time - the climb didn't count, so the
				// whole loop restarts rather than assuming the player is still mid-lap.
				advanceObstacleStage(ObstacleStage.OBSTACLE_PIPE, "no lap completion after Climb Rocks");
			}
			else
			{
				log.info("Wilderness Agility: no confirmation yet for {} after a while - still waiting", currentStage);
				pendingSinceTick = null;
			}
		}
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		GameState newState = event.getGameState();
		boolean loggedOut = newState == GameState.LOGIN_SCREEN || newState == GameState.HOPPING || newState == GameState.CONNECTION_LOST;

		if (newState == GameState.LOADING)
		{
			// A new scene is about to load, which rebases local tile coordinates - matches how
			// RuneLite's own built-in Agility plugin invalidates its obstacle cache on this exact
			// transition. A tracked object from the old scene would render its highlight at a wildly
			// wrong position if kept, so drop everything and let fresh spawn events repopulate it for
			// whatever's actually in the newly-loaded scene.
			stageObjectsByPosition.clear();
			preferredPositionByStage.clear();
			dispenserPosition = null;
		}

		if (loggedOut)
		{
			// Logged-out/away time shouldn't silently drag the XP and GP rates down - reset the
			// session immediately here rather than waiting for the next login's staleness check
			// (STALE_SESSION_THRESHOLD), which only catches an unclean shutdown, not a normal logout.
			totalProfit = 0;
			totalXpGained = 0;
			blightedFoodCount = 0;
			blightedPotionCount = 0;
			sessionStart = null;
			persistStats();

			if (wasInCourseLastTick)
			{
				streak = Math.max(0, streak - STREAK_LOGOUT_HOP_PENALTY);
				persistStreak();
				wasInCourseLastTick = false;
				configManager.setConfiguration(CONFIG_GROUP, KEY_WAS_IN_COURSE, false);
				restoreAgilityClickboxes();
			}
		}

		if (newState == GameState.LOGGED_IN)
		{
			resolveMode();
		}
	}

	@Subscribe
	public void onActorDeath(ActorDeath event)
	{
		if (event.getActor() == client.getLocalPlayer())
		{
			resetStreak();
		}
	}

	@Subscribe
	public void onItemContainerChanged(ItemContainerChanged event)
	{
		if (isInTargetArea())
		{
			log.debug("Wilderness Agility: ItemContainerChanged containerId={} (LOOTING_BAG={})",
				event.getContainerId(), InventoryID.LOOTING_BAG);
		}

		if (event.getContainerId() != InventoryID.LOOTING_BAG || !isInTargetArea())
		{
			return;
		}

		// The bag's contents only sync to the client when its interface is actually opened, so this
		// can't be relied on to fire automatically every lap (the chat-message parsing below is the
		// live/automatic source) - but when it does fire, it's ground truth, so it fully replaces
		// (not adds to) the tracked totals rather than risking double-counting against the chat path.
		long recomputedProfit = 0;
		int recomputedFood = 0;
		int recomputedPotion = 0;

		for (Item item : event.getItemContainer().getItems())
		{
			int id = item.getId();
			if (id <= 0)
			{
				continue;
			}

			if (BLIGHTED_FOOD_IDS.contains(id))
			{
				recomputedFood += item.getQuantity();
			}
			else if (BLIGHTED_POTION_IDS.contains(id))
			{
				recomputedPotion += item.getQuantity();
			}
			else
			{
				int canonicalId = itemManager.canonicalize(id);
				if (ARMOR_REWARD_IDS.contains(canonicalId))
				{
					recomputedProfit += valueItem(canonicalId, item.getQuantity());
				}
			}
		}

		totalProfit = recomputedProfit;
		blightedFoodCount = recomputedFood;
		blightedPotionCount = recomputedPotion;
		startSessionIfNeeded();
		updateRates();
		persistStats();
	}

	@Subscribe
	public void onStatChanged(StatChanged event)
	{
		if (event.getSkill() != Skill.AGILITY)
		{
			return;
		}

		int xp = event.getXp();
		if (lastAgilityXp == null)
		{
			lastAgilityXp = xp;
			return;
		}

		int delta = xp - lastAgilityXp;
		lastAgilityXp = xp;

		if (delta <= 0 || !isInTargetArea())
		{
			return;
		}

		log.info("Wilderness Agility: Agility XP delta={}", delta);

		// A real XP gain confirms the obstacle actually succeeded, but only if it's actually the
		// currently-expected obstacle that was just clicked - otherwise ANY small Agility XP gain while
		// in the area (e.g. repeatedly re-doing the same already-completed obstacle instead of the one
		// actually highlighted) would wrongly march the guide all the way to Rocks. The click doesn't
		// have to be checked/armed at click time (see onMenuOptionClicked) - that was the old design,
		// and it had its own race: a real click landing before the guide had caught up to that stage
		// (e.g. swinging on the ropeswing while the guide was still confirming the pipe) got silently
		// dropped, leaving the guide stuck. The size cap guards against unrelated Agility XP sources
		// while in the area, e.g. redeeming Wilderness agility tickets (confirmed live: 34,500 XP in
		// one event) - far too large to be a real single obstacle. Rocks/Dispenser are excluded: Rocks
		// is confirmed via the lap-completion chat message instead (onChatMessage below), and the
		// dispenser doesn't grant XP directly.
		Integer clickTick = currentStage == null ? null : lastClickTickByStage.get(currentStage);
		boolean recentlyClickedCurrentStage = clickTick != null
			&& client.getTickCount() - clickTick <= CLICK_CONFIRMATION_WINDOW_TICKS;

		if (currentStage != null && currentStage != ObstacleStage.ROCKS && currentStage != ObstacleStage.DISPENSER
			&& delta <= MAX_PLAUSIBLE_OBSTACLE_XP && recentlyClickedCurrentStage)
		{
			advanceObstacleStage(currentStage.next(), currentStage + " confirmed via XP gain");
		}
		else if (currentStage != null && currentStage != ObstacleStage.ROCKS && currentStage != ObstacleStage.DISPENSER
			&& delta <= MAX_PLAUSIBLE_OBSTACLE_XP)
		{
			log.info("Wilderness Agility: XP gain didn't match a recent click on {} - not advancing", currentStage);
		}

		totalXpGained += delta;
		startSessionIfNeeded();
		updateRates();
		persistStats();
	}

	@Subscribe
	public void onChatMessage(ChatMessage event)
	{
		String message = event.getMessage();
		if (message == null)
		{
			return;
		}

		boolean mentionsAgilityOrDispenser = GAME_MESSAGE_TYPES.contains(event.getType())
			&& (message.toLowerCase().contains("agility") || message.toLowerCase().contains("dispenser"));
		if (mentionsAgilityOrDispenser)
		{
			log.info("Wilderness Agility: chat message type={} text=\"{}\"", event.getType(), message);
		}

		// The dispenser is confirmed by ANY game-generated response mentioning it - a reward, or a
		// rejection (e.g. needing to finish a full lap first) - rather than one specific expected
		// message, since the exact rejection wording isn't confirmed. No preceding click is required,
		// for the same reason as the XP confirmation in onStatChanged above. Checked before the streak
		// match below so a lap-completion message (which also mentions "Agility") that just set
		// currentStage to DISPENSER doesn't immediately self-confirm in the same pass.
		if (currentStage == ObstacleStage.DISPENSER && mentionsAgilityOrDispenser)
		{
			advanceObstacleStage(currentStage.next(), "dispenser responded");
		}

		Matcher streakMatcher = STREAK_PATTERN.matcher(message);
		if (streakMatcher.find())
		{
			streak = Integer.parseInt(streakMatcher.group(1));
			streakConfirmed = true;
			persistStreak();

			// This message lands right as Climb Rocks (the final obstacle) is completed - confirming
			// the climb counted - so the obstacle guide advances to (or snaps back to) DISPENSER
			// regardless of exactly which stage it thought it was on.
			advanceObstacleStage(ObstacleStage.DISPENSER, "lap completion confirmed");
		}

		if (isInTargetArea())
		{
			parseDispenserReward(message);
		}
	}

	// Live/automatic GP and blighted-count source - fires every lap regardless of whether the
	// looting bag interface is open. The bag-check resync in onItemContainerChanged() above is the
	// fallback/ground-truth correction for whenever it is.
	private void parseDispenserReward(String message)
	{
		if (!message.contains("You have been awarded") || !message.contains("from the Agility dispenser"))
		{
			return;
		}

		// The trailing ", and an extra <item>" clause is deliberately not counted.
		int extraIndex = message.indexOf(", and an extra");
		String guaranteedSection = extraIndex >= 0 ? message.substring(0, extraIndex) : message;

		boolean anyAttributed = false;
		Matcher itemMatcher = DISPENSER_REWARD_ITEM_PATTERN.matcher(guaranteedSection);
		while (itemMatcher.find())
		{
			int quantity = Integer.parseInt(itemMatcher.group(1));
			String name = itemMatcher.group(2);
			Integer itemId = DISPENSER_REWARD_ITEM_IDS.get(name);
			if (itemId == null)
			{
				log.debug("Wilderness Agility: dispenser reward item '{}' not in the known table, skipping", name);
				continue;
			}

			if (BLIGHTED_FOOD_IDS.contains(itemId))
			{
				blightedFoodCount += quantity;
			}
			else if (BLIGHTED_POTION_IDS.contains(itemId))
			{
				blightedPotionCount += quantity;
			}
			else
			{
				totalProfit += valueItem(itemId, quantity);
			}

			anyAttributed = true;
		}

		if (anyAttributed)
		{
			startSessionIfNeeded();
			updateRates();
			persistStats();
		}
	}

	private long valueItem(int itemId, int quantity)
	{
		return alchemyMode
			? (long) itemManager.getItemComposition(itemId).getHaPrice() * quantity
			: (long) itemManager.getItemPrice(itemId) * quantity;
	}

	// Purely diagnostic - clicking an obstacle no longer drives the guide directly (see
	// advanceObstacleStage() directly (that would reintroduce the exact race this used to have: a real
	// click landing before the guide had caught up to that stage, e.g. clicking Ropeswing while the
	// guide was still confirming the pipe, would get silently dropped and leave the guide stuck) - it
	// instead just records which obstacle was clicked and when, so onStatChanged can later verify an XP
	// gain actually came from the obstacle currently expected rather than any small Agility XP gain.
	@Subscribe
	public void onMenuOptionClicked(MenuOptionClicked event)
	{
		ObstacleStage clickedStage = OBSTACLE_ID_TO_STAGE.get(event.getId());
		if (clickedStage != null)
		{
			lastClickTickByStage.put(clickedStage, client.getTickCount());
			log.info("Wilderness Agility: obstacle click - stage={}, option=\"{}\", objectId={}, currentStage={}",
				clickedStage, event.getMenuOption(), event.getId(), currentStage);
		}
	}

	@Subscribe
	public void onClientTick(ClientTick tick)
	{
		if (!isInTargetArea())
		{
			return;
		}

		for (MenuEntry entry : client.getMenuEntries())
		{
			if (!NPC_MENU_TYPES.contains(entry.getType()))
			{
				continue;
			}

			NPC npc = entry.getNpc();
			if (npc != null && SKELETON_NPC_IDS.contains(npc.getId()))
			{
				entry.setDeprioritized(true);
			}
		}
	}

	// Not every obstacle is necessarily a plain GameObject (a stepping stone or rock pile is quite
	// plausibly a GroundObject/DecorativeObject instead), so all four TileObject-bearing spawn event
