	// Always replaces whatever was cached at that exact position, matching RuneLite's own built-in
	// Agility plugin (which caches by direct replacement, with no "first wins" restriction) - the
	// point of keying by position rather than a single slot per stage is specifically so a legitimate
	// respawn is never blocked from refreshing the cached reference (which was the actual bug behind
	// only the frequently-respawning pipe rendering while everything else eventually stopped).
	private void trackObstacleObject(TileObject object)
	{
		// Defensive: a world hop/relogin mass-spawns every nearby object in one burst, and this threw
		// a run of NullPointerExceptions (with no stack trace captured - likely JIT's fast-throw
		// optimization on a hot repeated site) in exactly that situation. Rather than letting one bad
		// object crash this subscriber - and potentially stop it from ever tracking anything again
		// for the rest of the session - any unexpected failure here is swallowed and logged instead.
		try
		{
			if (object == null)
			{
				return;
			}

			ObstacleStage stage = OBSTACLE_ID_TO_STAGE.get(object.getId());
			if (stage == null)
			{
				return;
			}

			WorldPoint position = object.getWorldLocation();
			stageObjectsByPosition.computeIfAbsent(stage, s -> new HashMap<>()).put(position, object);
			log.info("Wilderness Agility: obstacle spawned - stage={}, objectId={}, position={}",
				stage, object.getId(), position);

			if (stage == ObstacleStage.DISPENSER)
			{
				dispenserPosition = position;
			}
			else if (!MULTI_TARGET_STAGES.contains(stage) && dispenserPosition != null)
			{
				WorldPoint currentPreferred = preferredPositionByStage.get(stage);
				if (currentPreferred == null
					|| position.distanceTo2D(dispenserPosition) < currentPreferred.distanceTo2D(dispenserPosition))
				{
					preferredPositionByStage.put(stage, position);
				}
			}
		}
		catch (RuntimeException e)
		{
			log.warn("Wilderness Agility: failed to track a spawned obstacle object", e);
		}
	}

	private void untrackObstacleObject(TileObject object)
	{
		try
		{
			if (object == null)
			{
				return;
			}

			ObstacleStage stage = OBSTACLE_ID_TO_STAGE.get(object.getId());
			if (stage == null)
			{
				return;
			}

			Map<WorldPoint, TileObject> byPosition = stageObjectsByPosition.get(stage);
			if (byPosition != null)
			{
				byPosition.remove(object.getWorldLocation());
			}
		}
		catch (RuntimeException e)
		{
			log.warn("Wilderness Agility: failed to untrack a despawned obstacle object", e);
		}
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (!CONFIG_GROUP.equals(event.getGroup()))
		{
			return;
		}

		if ("overlayPosition".equals(event.getKey()))
		{
			// A manually dragged position is saved by RuneLite and overrides setPosition() on its
			// own, so clear that saved override before applying the newly selected position.
			overlayManager.resetOverlay(overlay);
			overlay.setPosition(config.overlayPosition().getPosition());
		}
		else if ("valuationMode".equals(event.getKey()))
		{
			resolveMode();
		}
	}

	private void resolveMode()
	{
		// Ironman account-type detection was never reliable, so the mode is just whatever the player
		// picked directly rather than an "Auto" guess.
		alchemyMode = config.valuationMode() == WildernessAgilityConfig.ValuationMode.ALCHEMY;
		remindLootingBagIfResuming();
	}

	// Reminds the player to open their looting bag once the tracked totals are unverified against the
	// game's own record - specifically a plugin startup/relaunch that finds the last session ended
	// mid-course, since a fresh entry through the gate has no loot to check yet anyway. Runs from
	// resolveMode() so it fires whether the client was already logged in when the plugin started, or
	// logs in afterwards.
	private void remindLootingBagIfResuming()
	{
		if (!pendingResumeLootingBagReminder || client.getGameState() != GameState.LOGGED_IN)
		{
			return;
		}

		pendingResumeLootingBagReminder = false;
		client.addChatMessage(ChatMessageType.CONSOLE, "", LOOTING_BAG_REMINDER_MESSAGE, null);
	}

	private void startSessionIfNeeded()
	{
		if (sessionStart == null)
		{
			sessionStart = Instant.now();
		}
	}

	// Only recomputed when XP actually lands, not continuously - if it were live, the rate would
	// swing wildly in the first few seconds of a session before settling down.
	private void updateRates()
	{
		if (sessionStart == null)
		{
			xpPerHour = 0;
			return;
		}

		long elapsedMillis = Duration.between(sessionStart, Instant.now()).toMillis();
		if (elapsedMillis <= 0)
		{
			xpPerHour = 0;
			return;
		}

		xpPerHour = (int) Math.round(totalXpGained * 3_600_000.0 / elapsedMillis);
	}

	private int currentRegion()
	{
		Player local = client.getLocalPlayer();
		return local == null ? -1 : local.getWorldLocation().getRegionID();
	}

	private void resetStreak()
	{
		streak = 0;
		persistStreak();
	}

	private void advanceObstacleStage(ObstacleStage newStage, String reason)
	{
		currentStage = newStage;
		pendingSinceTick = client.getTickCount();
		log.info("Wilderness Agility: {} - obstacle guide advanced to {}", reason, currentStage);
	}

	private void suppressAgilityClickboxes()
	{
		if (clickboxesOverridden)
		{
			return;
		}

		originalShowClickboxes = configManager.getConfiguration(AGILITY_PLUGIN_CONFIG_GROUP, AGILITY_SHOW_CLICKBOXES_KEY, Boolean.class);
		configManager.setConfiguration(AGILITY_PLUGIN_CONFIG_GROUP, AGILITY_SHOW_CLICKBOXES_KEY, false);
		clickboxesOverridden = true;
	}

	private void restoreAgilityClickboxes()
	{
		if (!clickboxesOverridden)
		{
			return;
		}

		if (originalShowClickboxes == null)
		{
			configManager.unsetConfiguration(AGILITY_PLUGIN_CONFIG_GROUP, AGILITY_SHOW_CLICKBOXES_KEY);
		}
		else
		{
			configManager.setConfiguration(AGILITY_PLUGIN_CONFIG_GROUP, AGILITY_SHOW_CLICKBOXES_KEY, originalShowClickboxes);
		}

		clickboxesOverridden = false;
		originalShowClickboxes = null;
	}

	private void persistStats()
	{
		configManager.setConfiguration(CONFIG_GROUP, KEY_TOTAL_PROFIT, totalProfit);
		configManager.setConfiguration(CONFIG_GROUP, KEY_TOTAL_XP, totalXpGained);
		configManager.setConfiguration(CONFIG_GROUP, KEY_BLIGHTED_FOOD, blightedFoodCount);
		configManager.setConfiguration(CONFIG_GROUP, KEY_BLIGHTED_POTION, blightedPotionCount);
		configManager.setConfiguration(CONFIG_GROUP, KEY_SESSION_START, sessionStart == null ? -1L : sessionStart.toEpochMilli());
		configManager.setConfiguration(CONFIG_GROUP, KEY_LAST_UPDATE, Instant.now().toEpochMilli());
	}

	private void persistStreak()
	{
		configManager.setConfiguration(CONFIG_GROUP, KEY_STREAK, streak);
	}

	@Provides
	WildernessAgilityConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(WildernessAgilityConfig.class);
	}
}
